-- =============================================================================
-- 6. DOCS AND FILES
-- =============================================================================
-- PROVEN: a doc is a view of type 9; pages nest; flags public/archived/locked/wiki; page flags protected/seo/full_width;
--   generic links (link, backLink, externalLink); collab access-token endpoint.
-- ASSUMED: own docs table (core hints it may optionally link views.id), page body format (rich-text JSON),
--   CRDT state in a side table, versions.
CREATE TABLE docs (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  view_id uuid /* id -> views.views */,                 -- ASSUMED optional: the type-9 view row if the doc is shown in a view list
  name text NOT NULL DEFAULT '',
  parent_type text NOT NULL CHECK (parent_type IN ('workspace','space','folder','list')),  -- PROVEN: 12 = workspace; rest ASSUMED
  parent_id uuid NOT NULL,                           -- polymorphic
  visibility text NOT NULL DEFAULT 'private' CHECK (visibility IN ('private','workspace','public')),  -- PROVEN code 2 seen; names ASSUMED
  is_wiki boolean NOT NULL DEFAULT false,            -- PROVEN doc_type / Mark Wiki
  locked boolean NOT NULL DEFAULT false,
  settings jsonb NOT NULL DEFAULT '{}',              -- collapsed state, last page (PROVEN doc_settings)
  created_by uuid /* id -> identity.users */,
  archived_at timestamptz,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1
);

-- docs under a container (sidebar), live only.
CREATE INDEX docs_parent ON docs (workspace_id, parent_type, parent_id) WHERE deleted_at IS NULL AND archived_at IS NULL;

CREATE INDEX docs_wiki ON docs (workspace_id) WHERE is_wiki AND deleted_at IS NULL;

CREATE TABLE doc_tags (                              -- PROVEN doc tags; ASSUMED reuse of core tags
  doc_id uuid NOT NULL REFERENCES docs(id) ON DELETE CASCADE,
  tag_id uuid NOT NULL /* id -> tasks.tags */,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  PRIMARY KEY (doc_id, tag_id)
);

CREATE INDEX doc_tags_tag ON doc_tags (workspace_id, tag_id);

-- reaper for abandoned uploads (global)
CREATE TABLE doc_pages (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  doc_id uuid NOT NULL REFERENCES docs(id) ON DELETE CASCADE,
  parent_page_id uuid REFERENCES doc_pages(id),      -- PROVEN pages nest
  name text NOT NULL DEFAULT '',
  subtitle text,
  position text COLLATE "C" NOT NULL DEFAULT 'a0',   -- fractional ordering among siblings (PROVEN orderindex int; ours ASSUMED)
  content jsonb,                                     -- ASSUMED rich-text JSON; wire format not captured
  text_content text NOT NULL DEFAULT '',             -- plain text for search/previews
  icon text,
  color text,
  cover_file_id uuid /* id -> files.files */,
  full_width boolean NOT NULL DEFAULT false,
  is_public boolean NOT NULL DEFAULT false,
  seo_optimized boolean NOT NULL DEFAULT false,
  protected_by uuid /* id -> identity.users */,            -- PROVEN protected + note + who
  protected_note text,
  created_by uuid /* id -> identity.users */,
  edited_by uuid /* id -> identity.users */,
  edited_at timestamptz,
  archived_at timestamptz,
  archived_by uuid /* id -> identity.users */,
  deleted_at timestamptz,
  deleted_by uuid /* id -> identity.users */,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1
);

-- page tree of a doc.
CREATE INDEX doc_pages_tree ON doc_pages (workspace_id, doc_id, parent_page_id, position) WHERE deleted_at IS NULL;

-- 'recently edited pages by me'.
CREATE INDEX doc_pages_edited ON doc_pages (workspace_id, edited_by, edited_at DESC) WHERE deleted_at IS NULL;

-- co-editing state kept out of the hot row (ASSUMED CRDT blob; PROVEN only the collab access-token call).
CREATE TABLE doc_page_collab (
  page_id uuid PRIMARY KEY REFERENCES doc_pages(id) ON DELETE CASCADE,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  state bytea NOT NULL,
  state_version bigint NOT NULL DEFAULT 0,
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- page versions (ASSUMED): append-only snapshots; autosaves compacted by a retention job.
CREATE TABLE doc_page_versions (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  page_id uuid NOT NULL REFERENCES doc_pages(id) ON DELETE CASCADE,
  version_no integer NOT NULL,
  kind text NOT NULL DEFAULT 'autosave' CHECK (kind IN ('autosave','manual','restore')),
  name text,
  content jsonb NOT NULL,
  author_id uuid /* id -> identity.users */,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (page_id, version_no)
);

CREATE INDEX doc_page_versions_page ON doc_page_versions (workspace_id, page_id, version_no DESC);

-- history list

-- links: PROVEN generic link table (link, backLink, externalLink) across doc, page, task. App writes both rows of a back link.
CREATE TABLE doc_links (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  from_type text NOT NULL CHECK (from_type IN ('doc','page')),
  from_id uuid NOT NULL,
  to_type text NOT NULL CHECK (to_type IN ('task','doc','page','web')),
  to_id uuid,
  to_url text,
  kind text NOT NULL CHECK (kind IN ('link','backLink','externalLink')),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK ((to_type = 'web') = (to_url IS NOT NULL) AND (to_type = 'web') = (to_id IS NULL))
);

CREATE UNIQUE INDEX doc_links_uk ON doc_links (workspace_id, from_type, from_id, to_type, to_id, to_url, kind) NULLS NOT DISTINCT;

CREATE INDEX doc_links_to ON doc_links (workspace_id, to_type, to_id) WHERE to_id IS NOT NULL;
